/* ===== Новый вид (14.11.2026, по сводному макету владельца) =====
   Плитка без рамки, приподнятая тенью; итог — свечение внутрь от краёв (зелёное — принят, красное — отклонен, у органов — цвет органа);
   стадия — рамка своим цветом; карточка открывается отдельным окном со светящейся кромкой. */
const NV_STG: Record<string, [string, string]> = { r1: ['#8A6E00', '#D9BE45'], r2: ['#7F5AB5', '#B69CE6'], r3: ['#0A66D6', '#5AA2FF'], rat: ['#0B7C93', '#4FC3D9'], o: ['#5F5F66', '#A5A5AD'] };
const nvStg = (ty: string) => { const k = /^1/.test(ty) ? 'r1' : /^2/.test(ty) ? 'r2' : /^3/.test(ty) ? 'r3' : /ратиф/i.test(ty) ? 'rat' : 'o'; return NV_STG[k][DK ? 1 : 0]; };
const nvMix = (c: string, p: number) => `color-mix(in srgb, ${c} ${p}%, transparent)`;
const nvSh = () => (DK ? 'rgba(0,0,0,.45)' : 'rgba(20,30,50,.09)');
const nvGlow = (c: string) => `inset 0 0 9px 0 ${nvMix(c, 45)}, inset 0 0 0 1px ${nvMix(c, 45)}, 0 10px 20px ${nvSh()}`;
const nvTile = (c?: string): any => ({ border: 'none', borderRadius: 18, background: DK ? 'linear-gradient(#262C36,#1A1E25)' : 'linear-gradient(#FFFFFF,#EEF0F4)', boxShadow: c ? nvGlow(c) : `0 10px 20px ${nvSh()}, 0 2px 4px ${nvSh()}`, cursor: 'pointer', WebkitTapHighlightColor: 'transparent', minWidth: 0, boxSizing: 'border-box' });
const nvBlk = (): any => ({ background: DK ? '#262C37' : '#EDF1F7', boxShadow: `inset 0 0 0 1px ${DK ? '#353C49' : '#DCE3EE'}`, border: 'none', borderRadius: 14 });
const nvPill = (c: string): any => ({ display: 'inline-block', fontSize: 11.5, fontWeight: 600, lineHeight: 1.3, padding: '1px 9px', borderRadius: 9999, border: `1.5px solid ${c}`, color: c, whiteSpace: 'nowrap', maxWidth: '100%', overflow: 'hidden', textOverflow: 'ellipsis' });
function NvRing({ n, p, c, size }: { n: string; p: number; c: string; size?: number }) { const z = size || 44; return <span aria-hidden style={{ width: z, height: z, borderRadius: '50%', flex: 'none', display: 'grid', placeItems: 'center', background: `conic-gradient(${c} ${Math.max(0, Math.min(100, p))}%, ${DK ? '#2C323D' : '#E3E7EE'} 0)` }}><span style={{ width: z - 12, height: z - 12, borderRadius: '50%', display: 'grid', placeItems: 'center', background: DK ? '#20252E' : '#FFFFFF', fontSize: z > 50 ? 13 : 10.5, fontWeight: 700, fontVariantNumeric: 'tabular-nums' }}>{n}</span></span>; }
function NvBadge({ t, c, size }: { t: string; c: string; size?: number }) { const z = size || 46; return <span aria-hidden style={{ width: z, height: z, borderRadius: '50%', flex: 'none', boxSizing: 'border-box', border: `4px solid ${c}`, display: 'grid', placeItems: 'center', background: DK ? '#20252E' : '#FFFFFF' }}><span style={{ fontSize: t.length > 4 ? 8.5 : 11, fontWeight: 700, lineHeight: 1.05, textAlign: 'center', maxWidth: z - 12, overflowWrap: 'anywhere' }}>{t}</span></span>; }
/* Окно карточки: лист снизу на телефоне, окно по центру на компьютере; кромка светится цветом c. Закрытие: крестик, фон, Escape, «назад». */
function NvModal({ onClose, c, m, k, children }: { onClose: () => void; c: string; m?: boolean; k?: string; children: any }) {
  const t = useGrokTheme(); const cl = useRef(onClose); cl.current = onClose;
  useEffect(() => { const f = (e: any) => { if (e.key === 'Escape') cl.current(); }; const pop = () => cl.current(); document.addEventListener('keydown', f); window.addEventListener('popstate', pop); const po = document.body.style.overflow; document.body.style.overflow = 'hidden'; let pushed = false; let pu = ''; try { history.pushState({ ...(history.state || {}), gdm: 1 }, ''); pushed = true; pu = location.href; } catch (e) { /* история недоступна */ } return () => { document.removeEventListener('keydown', f); window.removeEventListener('popstate', pop); document.body.style.overflow = po; /* закрытие окна возвращает историю на шаг назад, только если адрес за время открытия не менялся (иначе фильтры/поиск потеряли бы новый адрес) */ if (pushed) setTimeout(() => { try { if (history.state && history.state.gdm) { if (location.href === pu) history.back(); else history.replaceState({ ...history.state, gdm: 0 }, '', location.href); } } catch (e) { /* история недоступна */ } }, 200); /* задержка: сначала успевает обновиться адрес поиска/фильтров */ }; }, []);
  return createPortal(<div data-gdmodal="1" onClick={() => onClose()} style={{ position: 'fixed', inset: 0, zIndex: 300, background: 'rgba(8,12,18,.55)', display: 'flex', alignItems: m ? 'flex-end' : 'center', justifyContent: 'center', padding: m ? 0 : 24, boxSizing: 'border-box', fontFamily: t.font.family, color: t.text.primary }}>
    <div data-gdwin={k || '1'} role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()} className="gd-anim" style={{ position: 'relative', width: '100%', maxWidth: m ? undefined : 920, maxHeight: m ? '90vh' : 'calc(100vh - 48px)', overflowY: 'auto', overscrollBehavior: 'contain', borderRadius: m ? '22px 22px 0 0' : 20, background: t.bg.base, boxShadow: `inset 0 0 9px 0 ${nvMix(c, 45)}, inset 0 0 0 1.5px ${nvMix(c, 60)}, 0 0 22px 2px ${nvMix(c, 30)}, 0 24px 60px rgba(0,0,0,.35)`, paddingBottom: 'env(safe-area-inset-bottom, 0px)' }}>
      {m && <div aria-hidden style={{ width: 38, height: 4, borderRadius: 2, background: t.border.default, margin: '8px auto 0' }} />}
      <button type="button" data-gdclose="1" aria-label="Закрыть" onClick={() => onClose()} style={{ position: 'absolute', top: m ? 10 : 12, right: 12, zIndex: 2, width: 32, height: 32, borderRadius: 16, border: 'none', background: 'transparent', color: t.text.secondary, fontSize: 22, lineHeight: 1, cursor: 'pointer' }}>×</button>
      {children}
    </div></div>, document.body);
}
function Donut({ v, size, center, sub, nw }: { v: number[]; size: number; center: string; sub?: string; nw?: boolean }) {
  const t = useGrokTheme();
  const d = t.dataviz;
  const colors = SYS; void d;
  const sum = v.reduce((a, b) => a + b, 0) || 1;
  let off = 0;
  const pt = (f: number, rad: number) => { const a = f * 2 * Math.PI - Math.PI / 2; return `${(50 + rad * Math.cos(a)).toFixed(3)} ${(50 + rad * Math.sin(a)).toFixed(3)}`; };
  const arc = (f0: number, f1: number) => { const big = f1 - f0 > 0.5 ? 1 : 0; return `M ${pt(f0, 47)} A 47 47 0 ${big} 1 ${pt(f1, 47)} L ${pt(f1, 33)} A 33 33 0 ${big} 0 ${pt(f0, 33)} Z`; };
  return (
    <svg viewBox="0 0 100 100" style={{ width: '100%', maxWidth: size, display: 'block', margin: '0 auto' }}>
      <title>{CATS.map((name, i) => `${name}: ${v[i]}`).join('\n')}</title>
      <path d={arc(0, 0.99999)} style={{ fill: t.border.subtle }} />
      {v.map((x, i) => {
        if (!x) return null;
        const a0 = off / sum;
        off += x;
        const a1 = Math.min(off / sum, 0.99999);
        return <path key={i} d={arc(a0, a1)} style={{ fill: colors[i] }} />;
      })}
      <text x="50" y={sub ? (nw && sub === 'за' ? 48 : 50) : 55} textAnchor="middle" fontSize="16" fontWeight={600} style={{ fill: t.text.primary, fontFamily: t.font.family }}>{center}</text>
      {sub && <text x="50" y={nw && sub === 'за' ? 64 : 63} textAnchor="middle" fontSize={nw && sub === 'за' ? 11 : 8} fontWeight={nw && sub === 'за' ? 600 : 400} style={{ fill: t.text.secondary, fontFamily: t.font.family }}>{sub}</text>}
    </svg>
  );
}

