const iniInfo = (s?: string): { label: string; segs: { k: 'dep' | 'sen' | 'org'; pl: boolean; body: string; orgs: string[] }[]; solo: boolean } | null => {
  if (!s || !s.trim()) return null;
  const segs = s.split(/;\s*/).filter((x) => x.trim()).map((seg) => {
    const mm = seg.match(/^(Депутаты Государственной Думы|Депутат Государственной Думы|Сенаторы Российской Федерации|Сенатор Российской Федерации)[\s,:]*/);
    if (mm) return { k: (/^Депутат/.test(mm[1]) ? 'dep' : 'sen') as 'dep' | 'sen', pl: /^(Депутаты|Сенаторы)/.test(mm[1]), body: seg.slice(mm[0].length).trim(), orgs: [] as string[] };
    const orgs = seg.split(/,\s*(?=[А-ЯЁ])/).map((x) => x.trim()).filter(Boolean);
    return { k: 'org' as const, pl: orgs.length > 1, body: seg.trim(), orgs };
  });
  const ord = { dep: 0, sen: 1, org: 2 } as const;
  segs.sort((x, y) => ord[x.k] - ord[y.k]);
  const fed = (o: string) => /^(Правительство|Президент|Верховный Суд|Конституционный Суд|Совет Федерации|Генеральный прокурор|Центральная избирательная|Счетная палата|Уполномоченный)/.test(o);
  const n = segs.reduce((a, g) => a + (g.k === 'org' ? g.orgs.length : g.pl ? 2 : 1), 0);
  const solo = segs.length === 1 && segs[0].k === 'org' && segs[0].orgs.length === 1;
  const types: string[] = [];
  segs.forEach((g) => {
    if (g.k === 'dep') types.push(g.pl ? 'депутаты Государственной Думы' : 'депутат Государственной Думы');
    else if (g.k === 'sen') types.push(g.pl ? 'сенаторы Российской Федерации' : 'сенатор Российской Федерации');
    else if (solo) types.push(g.orgs[0]);
    else {
      const f = g.orgs.filter(fed), r = g.orgs.filter((o) => !fed(o));
      f.forEach((o) => types.push(o));
      if (r.length) types.push(r.length > 1 ? 'законодательные органы субъектов Российской Федерации' : 'законодательный орган субъекта Российской Федерации');
    }
  });
  const tt = types.length > 1 ? types.slice(0, -1).join(', ') + ' и ' + types[types.length - 1] : types[0];
  return { label: (n > 1 ? 'Инициаторы' : 'Инициатор') + ' — ' + tt, segs, solo };
};
const iniView = (s?: string, b?: string): [string, any] | null => {
  const r = iniInfo(s); if (!r) return null;
  if (r.solo) return [r.label, '\u00a0'];
  const B = (x: string) => <b style={{ color: (DK ? '#409CFF' : 'rgb(10,100,214)') }}>{x}: </b>;
  const rows: any[] = [];
  r.segs.forEach((g, k) => {
    if (g.k === 'dep') rows.push(<span key={k}>{withParty(g.body, (b || '').split('-')[1])}</span>);
    else if (g.k === 'sen') rows.push(<span key={k}>{B(g.pl ? 'Сенаторы' : 'Сенатор')}{g.body}</span>);
    else g.orgs.forEach((o, j) => rows.push(<span key={k + '-' + j}>{o}</span>));
  });
  return [r.label, <span style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>{rows}</span>];
};
