const BP1112: Record<string, { sut: string[]; who: string }> = {"12387-9": {"sut": ["Россия ратифицирует соглашение с Беларусью об условиях деятельности Белорусско-Российского университета, подписанное 30 января 2026 года. Оно заменяет соглашение 2001 года и сохраняет преемственность правил для университета.", "Соглашение направлено на развитие учебной, научной, хозяйственной и финансовой деятельности университета и усиление инструментов управления им с учетом интересов учредителей."], "who": "Белорусско-Российский университет, его студенты и сотрудники."}, "155842-8": {"sut": ["В законе появляется понятие жилого комплекса — совокупности индивидуальных жилых домов и (или) земельных участков с общей инфраструктурой — и порядок управления и содержания имущества общего пользования в нем.", "Законопроект выполняет постановление Конституционного Суда от 28 декабря 2021 года № 55-П; вносятся также изменения в закон о государственной регистрации недвижимости."], "who": "Владельцы домов и участков в коттеджных поселках и других комплексах индивидуальных домов с общей инфраструктурой, управляющие организации."}, "827872-8": {"sut": ["Закон уточняет порядок предоставления свиданий подозреваемым и обвиняемым, содержащимся под стражей. Сейчас разрешается до двух свиданий в месяц до трех часов каждое, но порядок принятия решения и основания для свиданий в законе не определены, что приводит к многочисленным жалобам."], "who": "Подозреваемые и обвиняемые, содержащиеся под стражей, их родственники, следователи и суды, решающие вопрос о свиданиях."}, "1265998-8": {"sut": ["Законопроект уточняет требования к инвестиционным проектам резидентов Особой экономической зоны в Калининградской области. Цель — повысить инвестиционную привлекательность зоны в условиях санкционного давления и логистических ограничений."], "who": "Компании — резиденты Особой экономической зоны в Калининградской области и инвесторы региона."}, "1238813-8": {"sut": ["Законопроект устанавливает требования к проведению медицинских и фармацевтических научных мероприятий — конференций, семинаров, форумов.", "Цель — защитить граждан от недобросовестных организаций и лиц, которые проводят рекламные кампании под видом научной деятельности. Сейчас в законе не определено, что считается научным мероприятием и как его проводить."], "who": "Организаторы медицинских и фармацевтических конференций и форумов, врачи и пациенты."}, "1293142-8": {"sut": ["Законопроект устанавливает особенности регистрационных действий с некоторыми транспортными средствами — ввезенными в Россию и находящимися в международном розыске, в том числе по инициативе недружественных государств.", "Сейчас закон прямо запрещает регистрационные действия с такими машинами, что бьет по интересам их российских владельцев."], "who": "Владельцы автомобилей, ввезенных в Россию и объявленных в международный розыск, Госавтоинспекция."}, "1270300-8": {"sut": ["Законопроект касается использования пестицидов и агрохимикатов после завершения срока их государственной регистрации."], "who": "Сельхозпроизводители и другие пользователи пестицидов и агрохимикатов."}, "802324-8": {"sut": ["Законопроект устанавливает порядок информационного обеспечения в сфере управления имуществом регионов и муниципальным имуществом: процессы управления имуществом унифицируются и переводятся в цифровой вид, а данные обо всем государственном и муниципальном имуществе собираются вместе.", "Цель — повысить эффективность управления государственным и муниципальным имуществом и стимулировать экономический рост в регионах."], "who": "Органы власти регионов и органы местного самоуправления, управляющие имуществом."}, "386704-8": {"sut": ["Предлагалось запретить взыскание по исполнительным документам на имущество малоимущих граждан, купленное на деньги государственной социальной помощи, в том числе по социальному контракту."], "who": "Малоимущие граждане, получающие государственную социальную помощь, их кредиторы и судебные приставы."}, "644297-8": {"sut": ["Предлагалось ввести в КоАП административную ответственность за опасное вождение."], "who": "Водители."}, "346930-7": {"sut": ["Законопроект предлагал конкретизировать права собственника жилого помещения."], "who": "Собственники жилья."}, "1201396-8": {"sut": ["Законопроект уточняет, каким органам и лицам нотариусы выдают сведения о совершенных нотариальных действиях. Сейчас такие сведения выдаются по требованию суда, прокуратуры, следствия, судебных приставов и ряда других органов в связи с делами в их производстве."], "who": "Нотариусы, граждане и организации, обращающиеся к нотариусам, органы, запрашивающие сведения о нотариальных действиях."}, "1138192-8": {"sut": ["Законопроект касался использования средств видеофиксации при совершении нотариальных действий."], "who": "Нотариусы и граждане, обращающиеся к нотариусам."}, "301714-8": {"sut": ["Предлагалось принять Избирательный кодекс — единый федеральный акт с основными требованиями к проведению всех видов выборов в России. В основу проекта положен анализ федерального и регионального законодательства о выборах."], "who": "Избиратели, кандидаты, политические партии и избирательные комиссии."}, "301780-8": {"sut": ["Законопроект о порядке введения в действие Избирательного кодекса Российской Федерации; рассматривался вместе с проектом самого кодекса."], "who": "Избиратели, кандидаты, политические партии и избирательные комиссии."}, "667159-8": {"sut": ["Предлагалось отменить «муниципальный фильтр» для кандидатов в губернаторы, выдвинутых парламентскими партиями, — требование собрать подписи муниципальных депутатов и глав."], "who": "Кандидаты на выборах высших должностных лиц регионов от парламентских партий, избиратели."}, "1219137-8": {"sut": ["Предлагалось установить внеочередной порядок предоставления социальной выплаты на покупку жилья за пределами закрытого административно-территориального образования (ЗАТО) для отдельных категорий граждан, стоящих в очереди на такую выплату."], "who": "Жители ЗАТО, стоящие в очереди на выплату для переезда."}, "1235029-8": {"sut": ["Предлагалось обязать региональных операторов капремонта проводить техническое обследование многоквартирных домов не чаще одного раза в пять лет, а порядок обследования устанавливать на уровне регионов. Сейчас с 1 сентября 2024 года собственники могут заказать обследование за свой счет."], "who": "Собственники квартир в многоквартирных домах, региональные операторы капремонта."}, "1219255-8": {"sut": ["Предлагалось наделить регионы полномочиями организовывать бесплатное профессиональное обучение и дополнительное профессиональное образование многодетных родителей в государственных образовательных организациях за счет регионального бюджета."], "who": "Многодетные родители, органы власти регионов."}, "1116745-8": {"sut": ["Предлагалось распространить «кредитные каникулы» на заемщиков, применяющих упрощенную систему налогообложения, чтобы поддержать малый бизнес при росте долговой нагрузки и изменениях налогового регулирования."], "who": "Малые предприятия и предприниматели на упрощенной системе налогообложения, банки."}, "732180-8": {"sut": ["Предлагалось уточнить в федеральных конституционных законах о принятии в Россию ДНР, ЛНР, Запорожской и Херсонской областей положения о подтверждении прав на имущество, в том числе недвижимое, и гарантии при управлении имуществом с признаками бесхозяйного."], "who": "Жители и собственники имущества в ДНР, ЛНР, Запорожской и Херсонской областях."}, "1205311-8": {"sut": ["Предлагалось продлить сроки предоставления документов для государственной регистрации прав, ограничений и обременений на недвижимость в ДНР, ЛНР, Запорожской и Херсонской областях."], "who": "Собственники недвижимости в ДНР, ЛНР, Запорожской и Херсонской областях."}, "571170-8": {"sut": ["Предлагалось изменить законодательство о выборах для противодействия экстремизму и терроризму: не допускать в органы власти и избирательные комиссии граждан, причастных к экстремистской и террористической деятельности."], "who": "Кандидаты, члены избирательных комиссий, избиратели."}, "1087365-8": {"sut": ["Законопроект вводит механизм государственной регистрации ипотеки, которая обеспечивает обязательства по цифровым финансовым активам. Сейчас закон допускает такое обеспечение, но порядка его регистрации нет."], "who": "Выпускающие и покупающие цифровые финансовые активы, Росреестр."}, "1173283-8": {"sut": ["Предлагалось запретить интерактивные ставки, которые авторы называют главным двигателем роста числа игроков, и повысить возраст, с которого можно делать ставки на спорт, с 18 до 21 года."], "who": "Букмекеры и игроки, делающие ставки."}, "1188246-8": {"sut": ["Предлагалось вдвое увеличить административные штрафы за нарушения трудового законодательства и усилить ответственность за повторные нарушения — задержки зарплаты, нарушения режима отдыха и незаконные увольнения."], "who": "Работодатели и их должностные лица, работники."}, "1155209-8": {"sut": ["Предлагалось усилить ответственность организаций и предпринимателей, которые не имеют статуса ломбарда, но используют слово «ломбард» в названии и незаконно выдают потребительские займы."], "who": "Ломбарды и лица, незаконно выдающие займы под видом ломбардов, их клиенты."}, "1134416-8": {"sut": ["Предлагалось дать одному из многодетных родителей право на сокращенную продолжительность рабочего времени. Сейчас многодетные родители не входят в перечень работников с сокращенным рабочим временем."], "who": "Работающие многодетные родители и их работодатели."}, "1184861-8": {"sut": ["Предлагалось не привлекать граждан к административной ответственности за самостоятельное закрашивание надписей с рекламой наркотиков на фасадах, в подъездах и других общественных местах."], "who": "Жители домов, управляющие организации."}, "941255-8": {"sut": ["Предлагалось смягчить наказание за впервые совершенное и выявленное при любом виде контроля (надзора) правонарушение в предпринимательской деятельности — заменять штраф предупреждением."], "who": "Предприниматели и организации, контрольные (надзорные) органы."}, "1185523-8": {"sut": ["Предлагалось закрепить право подозреваемого или обвиняемого под домашним арестом посещать медицинские учреждения по медицинским показаниям, с доставкой туда и обратно транспортом контролирующего органа."], "who": "Подозреваемые и обвиняемые под домашним арестом, уголовно-исполнительные инспекции."}, "976700-8": {"sut": ["Предлагалось уточнить уголовную ответственность за отказ в предоставлении информации Федеральному Собранию или Счетной палате (статья 287 УК)."], "who": "Должностные лица, обязанные предоставлять информацию Федеральному Собранию и Счетной палате."}, "718538-8": {"sut": ["Предлагалось ввести уголовную ответственность за преступления с использованием технологий подмены личности — фальшивых видео- и аудиоматериалов с изображением или голосом человека, созданных в том числе нейросетями."], "who": "Граждане, чьи изображение и голос могут подделать; правоохранительные органы."}, "835835-8": {"sut": ["Предлагалось включить уполномоченных по правам ребенка в государственную систему бесплатной юридической помощи наравне с уполномоченными по правам человека."], "who": "Дети и их родители, нуждающиеся в бесплатной юридической помощи; уполномоченные по правам ребенка."}, "1159193-8": {"sut": ["Предлагалось ввести в КоАП новую статью 20.37 — штраф за нахождение в общественных местах с лицом, закрытым так, что нельзя установить личность."], "who": "Все граждане в общественных местах, полиция."}, "875232-8": {"sut": ["Предлагалось расширить гарантии при увольнении по инициативе работодателя для работников с семейными обязанностями, в том числе родителей из многодетных семей, статус которых по указу Президента № 63 устанавливается бессрочно."], "who": "Работающие родители, в том числе многодетные, и работодатели."}, "1243437-8": {"sut": ["Предлагалось установить административную ответственность за создание помех дорожному движению при незаконном размещении на дороге контейнеров для бытового и строительного мусора."], "who": "Организации и граждане, размещающие мусорные контейнеры, водители."}, "1234040-8": {"sut": ["Предлагалось установить особенности распоряжения предметом ипотеки, находящимся в общей собственности."], "who": "Совладельцы заложенной недвижимости, банки-залогодержатели."}, "1106697-8": {"sut": ["Предлагалось ввести новую категорию ветеранов — ветеранов трудовой деятельности — и меры социальной поддержки для них."], "who": "Граждане с большим трудовым стажем, не имеющие звания «Ветеран труда»."}, "1135826-8": {"sut": ["Предлагалось не включать выходные дни в число календарных дней ежегодного основного и дополнительного оплачиваемого отпуска."], "who": "Все работники по трудовому договору и работодатели."}, "788780-8": {"sut": ["Законопроект Государственного Собрания Мордовии уточнял процедуру продажи органом местного самоуправления земельной доли сельхозорганизации или фермерскому хозяйству, чтобы сделать ее открытой и обеспечить равный доступ всем покупателям."], "who": "Сельхозорганизации, фермерские хозяйства, органы местного самоуправления."}, "1185897-8": {"sut": ["Предлагалось обязать государственные и муниципальные медицинские организации информировать пациента об аудиоконтроле амбулаторного приема, чтобы защитить врачебную тайну."], "who": "Пациенты поликлиник, медицинские организации и врачи."}, "1082329-8": {"sut": ["Предлагалось дать дополнительные гарантии от увольнения руководителям (заместителям) выборных органов профсоюзных организаций, не освобожденным от основной работы, — в том числе обязательное предварительное согласие выборного профсоюзного органа при увольнении по ряду оснований."], "who": "Профсоюзные активисты и руководители первичных профсоюзных организаций, работодатели."}, "1101102-8": {"sut": ["Предлагалось ввести информирование супруга (бывшего супруга) о проведении искусственного прерывания беременности."], "who": "Женщины, обращающиеся за прерыванием беременности, их супруги, медицинские организации."}, "950309-8": {"sut": ["Предлагалось не допускать перевозки пассажиров и грузов водителями, которые не являются работниками перевозчика. По данным пояснительной записки, в России 6,95 млн грузовых автомобилей при примерно 496 тысячах работников в грузовом автотранспорте."], "who": "Перевозчики, водители грузовиков и автобусов, грузоотправители."}, "1120812-8": {"sut": ["Предлагалось сократить срок рассмотрения авиаперевозчиком претензии пассажира с 30 до 5 дней."], "who": "Авиапассажиры и авиакомпании."}, "1283945-8": {"sut": ["Предлагалось упростить оформление в собственность садовых и огородных участков гражданами, которые перестали быть членами СНТ из-за ликвидации товарищества или его исключения из ЕГРЮЛ."], "who": "Садоводы и огородники бывших СНТ."}, "1141606-8": {"sut": ["Предлагалось ввести в Трудовой кодекс временный адаптивный режим труда: работник с временными ограничениями здоровья может по своему заявлению и при наличии медицинского заключения продолжать работать в облегченном режиме, сохраняя доход."], "who": "Работники с временными нетяжелыми заболеваниями и работодатели."}, "1028160-8": {"sut": ["Предлагалось закрепить в законе пятидневную учебную неделю в школах и начало уроков не ранее 9 часов утра, а мероприятия, не предусмотренные учебным планом, проводить в выходные и праздничные дни."], "who": "Школьники, их родители и учителя."}, "1166815-8": {"sut": ["Предлагалось урегулировать использование лесов для отгонного животноводства."], "who": "Животноводы, ведущие отгонное животноводство, лесопользователи."}, "546827-8": {"sut": ["Предлагалось запретить в период избирательной кампании и кампании референдума лотереи и розыгрыши, в которых возможность получить приз зависит от способа голосования (программы вроде «Миллиона призов»). Цель — равенство прав участников выборов."], "who": "Избиратели, организаторы выборов и розыгрышей."}, "1149511-8": {"sut": ["Предлагалось расширить перечень мест, куда адвокат может пройти по удостоверению адвоката."], "who": "Адвокаты и их доверители."}, "725635-8": {"sut": ["Предлагалось распространить меры господдержки семей с детьми по погашению ипотеки на договоры купли-продажи жилья, приобретенного с рассрочкой платежа."], "who": "Многодетные семьи, купившие жилье в рассрочку."}, "809829-8": {"sut": ["Предлагалось дать супругам участников специальной военной операции право поступать в вузы на бакалавриат и специалитет в пределах отдельной квоты. Сейчас эта квота есть у самих участников СВО и их детей."], "who": "Супруги участников специальной военной операции, поступающие в вузы."}, "1275886-8": {"sut": ["Предлагалось ограничить право граждан приобретать отдельные виды гражданского оружия."], "who": "Граждане — владельцы и покупатели гражданского оружия."}, "1086546-8": {"sut": ["Предлагалось запретить размещать «алкомаркеты» — магазины, продающие алкогольную и спиртосодержащую продукцию, — в нежилых помещениях вновь построенных многоквартирных домов. Сейчас федерального запрета нет."], "who": "Жители новых многоквартирных домов, продавцы алкоголя, застройщики."}, "645714-8": {"sut": ["Предлагалось закрепить принцип «образование для всех, в течение всей жизни»: обеспечить право на образование независимо от возраста и установить гарантию ежегодных расходов на образование не менее 7% ВВП, а также налоговые льготы для тех, кто вкладывает средства в образование."], "who": "Учащиеся всех возрастов, учителя и образовательные организации."}, "640770-8": {"sut": ["Предлагалось ввести статус «детей войны» — граждан России, родившихся с 22 июня 1928 года по 3 сентября 1945 года, — и предоставить им льготы для улучшения материального положения."], "who": "Граждане, родившиеся с 22 июня 1928 года по 3 сентября 1945 года."}, "1123717-8": {"sut": ["Предлагалось наделить должностных лиц полиции полномочиями рассматривать административные дела о несоблюдении требований к содержанию животных."], "who": "Владельцы животных, полиция."}, "884791-8": {"sut": ["Предлагалось включить детей из многодетных семей в отдельную квоту бюджетного приема в вузы на бакалавриат и специалитет. Сейчас такое право есть у детей-сирот, инвалидов и ветеранов боевых действий."], "who": "Дети из многодетных семей, поступающие в вузы."}, "1249894-8": {"sut": ["Предлагалось дать гражданам право оплачивать отопление по показаниям индивидуальных приборов учета независимо от решений общих собраний собственников и решений органов власти регионов."], "who": "Жители многоквартирных домов с индивидуальными приборами учета тепла, управляющие компании."}, "1272398-8": {"sut": ["Предлагалось прямо запретить в Жилищном кодексе индексацию платы граждан за коммунальные услуги чаще одного раза в календарный год. В 2026 году индексаций было две: с 1 января — на 1,7% и с 1 октября — от 8% до 22% в зависимости от региона."], "who": "Все граждане, оплачивающие коммунальные услуги."}, "576323-7": {"sut": ["Предлагалось восстановить в полном объеме социальные и пенсионные права участников Великой Отечественной войны для военнослужащих, служивших с 22 июня 1941 по 3 сентября 1945 года не менее шести месяцев в частях, не входивших в действующую армию, и награжденных за службу в этот период."], "who": "Ветераны — военнослужащие тыловых частей и учреждений времен Великой Отечественной войны."}, "712846-8": {"sut": ["Предлагалось установить особенности трудоустройства лиц до 18 лет, чтобы расширить возможности их работы и снизить кадровый дефицит."], "who": "Подростки до 18 лет, ищущие работу, и работодатели."}, "1131746-8": {"sut": ["Предлагалось разрешить вузам и другим образовательным организациям ежегодно повышать стоимость платного обучения не выше уровня инфляции, а для отдельных категорий обучающихся — запретить повышать ее вовсе."], "who": "Студенты, обучающиеся платно, и их родители; вузы."}, "1077407-8": {"sut": ["Предлагалось ограничить право иностранных граждан приобретать отдельные виды оружия и конструктивно сходные с оружием изделия."], "who": "Иностранные граждане в России, продавцы оружия."}, "154609-8": {"sut": ["Предлагалось установить статус ветерана боевых действий для лиц, участвовавших в боевых действиях в составе Народного ополчения Донбасса, Народной милиции ДНР и ЛНР, с положенными мерами социальной поддержки."], "who": "Бойцы Народного ополчения Донбасса, Народной милиции ДНР и ЛНР и члены их семей."}, "1207484-8": {"sut": ["Предлагалось дать отцу несовершеннолетнего ребенка ежегодный дополнительный неоплачиваемый отпуск для посещения дошкольных, школьных, спортивных, волонтерских и военно-патриотических мероприятий."], "who": "Работающие отцы несовершеннолетних детей, работодатели."}, "1116772-8": {"sut": ["Предлагалось предоставлять многодетным гражданам земельные участки, обеспеченные инфраструктурой."], "who": "Многодетные семьи, получающие земельные участки."}, "990638-8": {"sut": ["Предлагалось запретить заниматься педагогической деятельностью лицам, употреблявшим наркотические средства или психотропные вещества либо пропагандировавшим наркотики."], "who": "Педагоги и кандидаты на работу в образовании, учащиеся и их родители."}, "917534-8": {"sut": ["Предлагалось установить квоты для приема на работу ветеранов боевых действий, чтобы дать им дополнительные гарантии занятости и поддержать работодателей."], "who": "Ветераны боевых действий, в том числе участники СВО, и работодатели."}, "1257307-8": {"sut": ["Предлагалось, чтобы решение Банка России об установлении ключевой ставки выше 7% годовых принималось с согласия Государственной Думы, и оценивалось ее влияние на доступность ипотеки."], "who": "Банк России, заемщики, в том числе по ипотеке, банки."}, "912124-8": {"sut": ["Предлагалось установить статус «детей Великой Победы» для граждан, родившихся с 22 июня 1928 года по 9 мая 1945 года, и предоставить им меры социальной поддержки."], "who": "Граждане, родившиеся с 22 июня 1928 года по 9 мая 1945 года."}, "1085777-8": {"sut": ["Предлагалось запретить иностранным гражданам и лицам без гражданства носить в России ножи и другое режущее, колющее, рубящее оружие, которое по классификации не относится к холодному оружию."], "who": "Иностранные граждане и лица без гражданства в России."}, "193504-8": {"sut": ["Предлагалось отнести к ветеранам боевых действий военнослужащих, выполнявших задачи на Кубе в ходе операции «Анадырь» во время Карибского кризиса — с 1 июля 1962 по 30 ноября 1963 года. Туда было направлено около 43 тысяч военнослужащих."], "who": "Участники операции «Анадырь» на Кубе в 1962–1963 годах."}, "1003940-8": {"sut": ["Предлагалось предоставлять родителям (усыновителям, опекунам, попечителям, приемным родителям) школьников однодневный отпуск без сохранения заработной платы в связи с началом учебного года. Сейчас такой выходной можно получить только по соглашению с работодателем."], "who": "Работающие родители школьников и работодатели."}, "867505-8": {"sut": ["Предлагалось установить единые по всей стране меры поддержки участников специальной военной операции и членов их семей. Сейчас поддержка, которую дают регионы, сильно отличается в зависимости от места жительства участника."], "who": "Участники СВО и члены их семей."}, "1208253-8": {"sut": ["Предлагалось обязательно устанавливать прилегающие территории у остановок общественного транспорта, на которых нельзя продавать алкоголь. Сейчас запрет действует только в границах самой остановки, и алкомаркеты открываются в 2–5 метрах от нее."], "who": "Продавцы алкоголя, пассажиры общественного транспорта, органы местного самоуправления."}, "25978-9": {"sut": ["Россия ратифицирует договор с Королевством Камбоджа о передаче лиц, осужденных к лишению свободы. Президент внес законопроект 3 ноября 2026 года; Госдума приняла закон 11 ноября."], "who": "Граждане России, осужденные в Камбодже, и граждане Камбоджи, осужденные в России."}, "25979-9": {"sut": ["Россия ратифицирует договор с Республикой Зимбабве о передаче для отбывания наказания лиц, осужденных к лишению свободы. Президент внес законопроект 3 ноября 2026 года; Госдума приняла закон 11 ноября."], "who": "Граждане России, осужденные в Зимбабве, и граждане Зимбабве, осужденные в России."}, "1024261-8": {"sut": ["Предлагалось расширить перечень случаев бесплатного предоставления государственных и муниципальных земельных участков гражданам в собственность — в частности, семьям, которые долго состоят в браке и воспитывают детей."], "who": "Семьи с детьми, давно состоящие в браке; органы власти, распоряжающиеся землей."}, "332027-8": {"sut": ["Проводится эксперимент по дистанционной продаже через специализированный сайт «Почты России» вина, крепленого и игристого вина из винограда, выращенного в России или в странах ЕАЭС при подтверждении места его произрастания."], "who": "Российские винодельческие хозяйства, «Почта России», покупатели вина."}, "332033-8": {"sut": ["Из закона об обороте алкоголя исключается запрет дистанционной торговли для эксперимента по продаже через интернет вина, крепленого и игристого вина из российского винограда. Законопроект сопровождает закон о самом эксперименте."], "who": "Российские винодельческие хозяйства, «Почта России», покупатели вина."}, "21049-9": {"sut": ["В стаж муниципальной службы будут включаться периоды военной службы и службы в органах внутренних дел. Цель — расширить гарантии для военнослужащих, в том числе выпускников программы «Время героев» для участников и ветеранов СВО."], "who": "Военнослужащие, сотрудники органов внутренних дел и ветераны СВО, поступающие на муниципальную службу."}, "1208451-8": {"sut": ["Предлагалось упорядочить и повысить качество оценки регулирующего воздействия муниципальных нормативных правовых актов — процедуры, которая проверяет, не создают ли такие акты лишних обязанностей для бизнеса."], "who": "Органы местного самоуправления, предприниматели."}, "1059864-7": {"sut": ["Предлагалось признавать безработными самозанятых, индивидуальных предпринимателей без наемных работников и работников, не обеспеченных работой, в условиях особых правовых режимов и выплачивать им пособие по безработице."], "who": "Самозанятые, индивидуальные предприниматели без работников, работники, оставшиеся без работы."}, "1278814-8": {"sut": ["Законопроект защищает права граждан при взыскании их денежных средств: сумму задолженности, до которой не допускается арест имущества должника, предлагается индексировать с учетом инфляции, а арест на деньги налагать только в размере долга и расходов на исполнение."], "who": "Должники по исполнительным производствам, кредиторы, судебные приставы."}, "1336438-8": {"sut": ["Законопроект совершенствует порядок планирования картографических работ за счет бюджета: регионы направляют уведомления о планируемых работах, а «Роскадастр» и органы власти регионов взаимно информируют друг друга о таких работах."], "who": "Органы власти регионов, ППК «Роскадастр», заказчики и исполнители картографических работ."}, "1231059-8": {"sut": ["Предлагалось разрешить создавать центры пробации коммерческим организациям, на базе которых работают участки исправительных центров. Сейчас центры пробации могут создавать только некоммерческие организации и общественные объединения, и у них не хватает средств."], "who": "Лица, освободившиеся из мест лишения свободы, организации, где работают участки исправительных центров."}, "635551-8": {"sut": ["Предлагалось установить меры социальной поддержки граждан, пострадавших в результате террористических актов и чрезвычайных ситуаций."], "who": "Граждане, пострадавшие от терактов и чрезвычайных ситуаций, и их семьи."}, "1062674-8": {"sut": ["Предлагалось установить дополнительные социальные гарантии гражданам, пострадавшим от террористических актов."], "who": "Граждане, пострадавшие от терактов, и их семьи."}, "564208-7": {"sut": ["Предлагалось распространить статус ветерана боевых действий на военнослужащих Вооруженных Сил СССР, направлявшихся в Чехословакию с 21 августа по ноябрь 1968 года в составе войск стран Варшавского договора (операция «Дунай»)."], "who": "Участники операции «Дунай» в Чехословакии в 1968 году."}, "1025004-8": {"sut": ["Предлагалось обеспечить бесплатным горячим питанием один раз в день учеников 5–11 классов государственных и муниципальных школ. Сейчас по закону с 1 сентября 2020 года бесплатное горячее питание положено только ученикам начальной школы."], "who": "Ученики 5–11 классов и их родители, школы, региональные и местные бюджеты."}, "909648-8": {"sut": ["Предлагалось закрепить федеральные гарантии для отдельных категорий граждан, пострадавших в период Великой Отечественной войны, в том числе ежемесячную выплату 1000 рублей всем гражданам со статусом детей Великой Отечественной войны."], "who": "Граждане, пострадавшие в период Великой Отечественной войны, в том числе дети войны."}, "1186017-8": {"sut": ["Предлагалось наделить Генеральную прокуратуру полномочиями по надзору за исполнением законодательства Центральным банком."], "who": "Банк России, Генеральная прокуратура."}, "992203-8": {"sut": ["Предлагалось дать участникам СВО и ветеранам боевых действий, у которых трое и более несовершеннолетних детей, право бесплатного проезда по платным автомобильным дорогам и платным участкам дорог."], "who": "Участники СВО и ветераны боевых действий с тремя и более несовершеннолетними детьми."}, "1246854-8": {"sut": ["Предлагалось снизить возраст для компенсации взноса на капитальный ремонт неработающим собственникам жилья: 50% — с 65 лет вместо 70, 100% — с 70 лет вместо 80."], "who": "Неработающие пенсионеры — собственники квартир в многоквартирных домах."}, "1125149-8": {"sut": ["Предлагалось ограничить рост платы граждан за коммунальные услуги, закрепив в Жилищном кодексе ограничения на размер предельных индексов ее изменения. В 2026 году индексы менялись с 1 января и с 1 октября (до 22%)."], "who": "Все граждане, оплачивающие коммунальные услуги."}, "1231152-8": {"sut": ["Предлагалось ввести ежемесячное пособие не ниже МРОТ неработающим матерям, отцам или опекунам, воспитывающим двух и более детей, до достижения детьми семи лет. Сейчас пособие по уходу за ребенком платится только до 1,5 лет."], "who": "Неработающие родители и опекуны двух и более детей до семи лет."}, "1262373-8": {"sut": ["Предлагалось дать детям, получившим тяжкий или средней тяжести вред здоровью от обстрелов и терактов вооруженных формирований Украины, особые права при поступлении в колледжи и вузы и сохранить это право после совершеннолетия."], "who": "Дети, пострадавшие от обстрелов и терактов, в том числе в приграничных регионах."}, "619425-8": {"sut": ["Предлагалось дополнить перечень стран и боевых действий в законе «О ветеранах», чтобы отнести к ветеранам боевых действий воинов-интернационалистов, которые сейчас в перечень не попадают, — например, служивших на Кубе с 1962 года."], "who": "Бывшие военнослужащие — участники военных операций на территориях других государств."}, "1212357-8": {"sut": ["Предлагалось исключить возможность утверждать генеральные планы, правила землепользования и застройки, проекты планировки и межевания территории и изменения в них без общественных обсуждений или публичных слушаний."], "who": "Жители городов и поселков, органы местного самоуправления, застройщики."}, "1123705-8": {"sut": ["Предлагалось закрепить право бесплатной парковки одного автомобиля члена многодетной семьи на платных парковках в порядке, определяемом Правительством. В России более 2,5 млн многодетных семей."], "who": "Многодетные семьи с автомобилем."}, "731276-8": {"sut": ["Предлагалось дополнить принципы государственной политики в сфере образования и правовой статус педагогического работника защитой его чести и достоинства."], "who": "Учителя и другие педагогические работники."}};
