  const toast = (s: string) => { setOk(s); clearTimeout(tm.current); tm.current = setTimeout(() => setOk(''), 2200); };
  const go = async (e: any) => { e.stopPropagation(); const u = shareLink(day, id); const nav: any = navigator; if (m && nav.share) { try { await nav.share({ title: 'Календарь законов', url: u }); return; } catch (er: any) { if (er && er.name === 'AbortError') return; } } try { await nav.clipboard.writeText(u); toast('Ссылка на карточку скопирована'); } catch (er) { try { const ta = document.createElement('textarea'); ta.value = u; ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); toast('Ссылка на карточку скопирована'); } catch (e2) { toast(u); } } };
