/* 12.11.2026: во вкладке «Новости» — только материалы лент новостей (duma.gov.ru/news, government.ru/news, kremlin.ru/events, council.gov.ru/events/news). Голосования, акты и заседания — в календаре, здесь не дублируются. */
const NEWSU = /^https?:\/\/(www\.)?(duma\.gov\.ru\/news\/|government\.ru\/news\/|kremlin\.ru\/events\/|council\.gov\.ru\/events\/news\/)/;
const newsOnly = (fs: Record<string, FSub[]>): Record<string, FSub[]> => { const r: Record<string, FSub[]> = {}; for (const k of Object.keys(fs)) r[k] = fs[k].map(([h, it]) => [h, it.filter((x) => NEWSU.test(x[1] || ''))] as FSub).filter(([, it]) => it.length > 0); return r; };
