const SFI: any[] = [{"o": "sf", "d": "10.11.2026", "ty": "заседание", "k": "", "stt": "Принято", "t": "Совет Федерации сформировал сенаторскую часть Межпарламентской группы РФ для участия в международных мероприятиях", "st": "Совет Федерации сформировал сенаторскую часть Межпарламентской группы РФ для участия в международных мероприятиях", "u": "http://council.gov.ru/events/news/178212/", "x": "Также приняты постановления о внесении изменений в составах комитетов и Комиссии СФ.", "sut": "Сенаторы приняли решение о формировании сенаторской части Межпарламентской группы Федерального Собрания РФ. Сопредседателем Межпарламентской группы РФ избрана Председатель СФ Валентина Матвиенко. Заместитель Председателя СФ Константин Косачев избран заместителем сопредседателя Межпарламентской группы РФ. Межпарламентская группа из всех сенаторов РФ и депутатов ГД создается для обеспечения участия российских парламентариев в деятельности Межпарламентского союза и поддержания межпарламентских контактов в рамках групп по сотрудничеству с парламентами (палатами парламентов) иностранных государств.", "sfi": 1}, {"o": "sf", "d": "10.11.2026", "ty": "заседание", "k": "", "stt": "Кандидатура поддержана", "t": "Сенаторы поддержали кандидатуру О. Логунова для назначения на должность заместителя Генерального прокурора РФ", "st": "Сенаторы поддержали кандидатуру О. Логунова для назначения на должность заместителя Генерального прокурора РФ", "u": "http://council.gov.ru/events/news/178213/", "sut": "Председатель Комитета СФ по конституционному законодательству и государственному строительству Андрей Клишас проинформировал о результатах рассмотрения представленной Президентом Российской Федерации для проведения консультаций кандидатуры Олега Логунова на должность заместителя Генерального прокурора РФ. «Профильные комитеты Совета Федерации, в соответствии с обновленными положениями Конституции РФ, со статьей о Прокуратуре РФ и положениями Регламента, рассмотрели представленную Президентом кандидатуру Олега Логунова. Консультации состоялись, кандидатура сенаторами поддержана.", "sfi": 1}, {"o": "sf", "d": "10.11.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Сенаторы одобрили ратификацию Договора между Россией и Зимбабве о взаимной правовой помощи по уголовным делам", "st": "Сенаторы одобрили ратификацию Договора между Россией и Зимбабве о взаимной правовой помощи по уголовным делам", "u": "http://council.gov.ru/events/news/178214/", "x": "Документ представил первый заместитель председателя Комитета СФ по международным делам Г. Карасин.", "sut": "На 622-м заседании Совет Федерации одобрил ратификацию Договора между Российской Федерацией и Республикой Зимбабве о взаимной правовой помощи по уголовным делам. В соответствии с Договором стороны оказывают друг другу взаимную правовую помощь по уголовным делам. Такая помощь оказывается, если деяние, в связи с которым поступил запрос о правовой помощи, является уголовно наказуемым согласно законодательству обеих сторон.", "sfi": 1}, {"o": "sf", "d": "10.11.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Ратификация Соглашения между РФ и Камбоджей направлена на взаимную защиту граждан в области международной уголовной юстиции", "st": "Ратификация Соглашения между РФ и Камбоджей направлена на взаимную защиту граждан в области международной уголовной юстиции", "u": "http://council.gov.ru/events/news/178215/", "x": "Документ представил первый заместитель председателя Комитета СФ по международным делам А. Келин.", "sut": "На 622-м заседании Совет Федерации одобрил ратификацию Соглашения между Российской Федерацией и Королевством Камбоджа о взаимной защите граждан в области международной уголовной юстиции. Соглашение направлено на создание международно-правовой основы сотрудничества между Россией и Королевством Камбоджа в уголовно-правовой сфере в целях защиты прав и свобод граждан государств-участников соглашения от нарушений в области международной уголовной юстиции.", "sfi": 1}, {"o": "sf", "d": "10.11.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Сенаторы одобрили ратификацию договоров с Никарагуа о выдаче и передаче осужденных", "st": "Сенаторы одобрили ратификацию договоров с Никарагуа о выдаче и передаче осужденных", "u": "http://council.gov.ru/events/news/178216/", "x": "Соглашения будут способствовать правосудию и защите законных интересов граждан, заявил А. Мешков.", "sut": "Совет Федерации одобрил два федеральных закона о ратификации договоров между Российской Федерацией и Республикой Никарагуа – о выдаче и о передаче для отбывания наказания лиц, осужденных к лишению свободы. «Ратификация договоров будет способствовать развитию сотрудничества между Россией и Никарагуа в уголовно-правовой сфере, достижению целей правосудия, обеспечению прав и законных интересов наших граждан», – заявил парламентарий.", "sfi": 1}, {"o": "sf", "d": "10.11.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Россия и Беларусь уточнили перечни категорий налогоплательщиков, освобождаемых от НДС", "st": "Россия и Беларусь уточнили перечни категорий налогоплательщиков, освобождаемых от НДС", "u": "http://council.gov.ru/events/news/178218/", "x": "Документ представила Е. Афанасьева.", "sut": "Совет Федерации одобрил Федеральный закон «О ратификации Протокола о внесении изменений в Договор между Российской Федерацией и Республикой Беларусь об общих принципах налогообложения по косвенным налогам от 3 октября 2022 года». Заместитель председателя Комитета СФ по международным делам Елена Афанасьева пояснила, что в связи с изменениями в налоговых законодательствах двух стран документом актуализируются перечни категорий налогоплательщиков, освобождаемых от НДС, а также операций, освобождаемых от налога и облагаемых по пониженной и нулевой ставкам. Кроме того, документ дополняется информацией о минимальных налоговых ставках акцизов.", "sfi": 1}, {"o": "sf", "d": "10.11.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Соглашение между Россией и Южной Осетией направлено на дальнейшее развитие сотрудничества в таможенной сфере", "st": "Соглашение между Россией и Южной Осетией направлено на дальнейшее развитие сотрудничества в таможенной сфере", "u": "http://council.gov.ru/events/news/178219/", "x": "Документ представил член Комитета СФ по международным делам А. Кондратьев.", "sut": "На 622-м заседании Совет Федерации одобрил ратификацию Соглашения между Российской Федерацией и Республикой Южная Осетия о взаимном зачете в выслугу лет службы в таможенных органах двух стран. Соглашение было подписано в Цхинвале 20 сентября 2025 г. Соглашение направлено на дальнейшее развитие сотрудничества в таможенной сфере, а также на решение вопросов социальной защиты сотрудников таможенных органов на территориях двух государств.", "sfi": 1}, {"o": "sf", "d": "10.11.2026", "ty": "заседание", "k": "", "stt": "Выступление эксперта", "t": "В рамках «Времени эксперта» на заседании СФ выступила заместитель директора Института народнохозяйственного прогнозирования РАН О. Кузнецова", "st": "В рамках «Времени эксперта» на заседании СФ выступила заместитель директора Института народнохозяйственного прогнозирования РАН О. Кузнецова", "u": "http://council.gov.ru/events/news/178220/", "x": "Развитие современных технологий, рост новых производств влияют на трансформацию расселения и концентрацию населения, отметила учёный.", "sut": "На 622-м заседании Совета Федерации в рамках рубрики «Время эксперта» выступила заместитель директора Института народнохозяйственного прогнозирования Российской академии наук Ольга Кузнецова. Тема выступления — проектом Стратегии пространственного развития РФ на период до 2030 года с прогнозом до 2036 года. Эксперт проанализировала ключевые направления и вызовы, которые этот документ должен учитывать.", "sfi": 1}, {"o": "sf", "d": "10.11.2026", "ty": "заседание", "k": "", "stt": "Выступления сенаторов", "t": "Сенаторы РФ обсудили вопросы сохранения культурного наследия и результаты проведения Дней креативной экономики", "st": "Сенаторы РФ обсудили вопросы сохранения культурного наследия и результаты проведения Дней креативной экономики", "u": "http://council.gov.ru/events/news/178221/", "x": "На «парламентской разминке» были затронуты также темы создания Единой территории опережающего развития, строительства судов и развития архивного дела.", "sut": "На 622-м заседании Совета Федерации сенаторы РФ выступили по актуальным социально-экономическим и политическим вопросам. Член Комитета по федеративному устройству, региональной политике, местному самоуправлению и делам Севера Василий Голубев затронул тему восстановления объектов культурного наследия. «В законодательстве отсутствует режим перевода ОКН из категории многоквартирный дом в нежилое здание, действующий порядок требует от муниципалитетов значительных затрат», — пояснил сенатор. Он предложил урегулировать этот механизм.", "sfi": 1}, {"o": "sf", "d": "10.11.2026", "ty": "заседание", "k": "", "stt": "Доклад", "t": "Заместитель Председателя Банка России рассказала сенаторам о преимуществах цифрового рубля", "st": "Заместитель Председателя Банка России рассказала сенаторам о преимуществах цифрового рубля", "u": "http://council.gov.ru/events/news/178222/", "x": "З. Кахруманова подчеркнула равноправие новой формы национальной валюты с наличным и безналичным рублем.", "sut": "На пленарном заседании Совета Федерации с докладом о внедрении и развитии цифрового рубля выступила заместитель Председателя Центрального банка РФ Зульфия Кахруманова. Она напомнила, что с 1 сентября текущего года проект по внедрению цифрового рубля перешел от этапа пилотирования к широкому внедрению. «Теперь каждый гражданин старше 18 лет может открыть счет цифрового рубля и совершать операции через крупнейшие банки». По словам зампреда Банка России, это стало возможным благодаря проработанной законодательной базе, в создании которой принимали участие сенаторы.", "sfi": 1}, {"o": "sf", "d": "10.11.2026", "ty": "заседание", "k": "", "stt": "Правительственный час", "t": "Министр внутренних дел РФ рассказал о мерах по противодействию незаконной миграции", "st": "Министр внутренних дел РФ рассказал о мерах по противодействию незаконной миграции", "u": "http://council.gov.ru/events/news/178223/", "x": "В. Колокольцев выступил в рамках «правительственного часа» на заседании Совета Федерации.", "sut": "Владимир Колокольцев отметил, что противодействие незаконной миграции — одна из ключевых задач государственной политики, призванная обеспечить национальную безопасность и защищённость населения страны. Он сообщил, что Указом Президента РФ в апреле прошлого года в МВД создана Служба по вопросам гражданства и регистрации иностранных граждан. «Принята новая Концепция государственной миграционной политики, важная роль в реализации которой отводится органам внутренних дел».", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Приглашён", "t": "На 622-е заседание Совета Федерации приглашен Министр внутренних дел РФ В. Колокольцев", "st": "На 622-е заседание Совета Федерации приглашен Министр внутренних дел РФ В. Колокольцев", "u": "http://council.gov.ru/events/news/177919/", "x": "Глава МВД выступит перед сенаторами на тему незаконной миграции.", "sut": "На 622-е заседание Совета Федерации приглашен Министр внутренних дел Российской Федерации Владимир Колокольцев.", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Удостоверения вручены", "t": "На заседании Совета Федерации представлены новые сенаторы", "st": "На заседании Совета Федерации представлены новые сенаторы", "u": "http://council.gov.ru/events/news/177918/", "x": "Ряд сенаторов переподтвердили свои полномочия.", "sut": "Председатель Совета Федерации Валентина Матвиенко на 621-м заседании вручила удостоверения и нагрудные знаки новым сенаторам. Это представители в СФ от законодательных органов государственной власти: Республики Мордовия – Ольга Македонская, Липецкой области – Евгений Саввин, Приморского края – Жанна Гудкова, от исполнительного органа государственной власти Луганской Народной Республики – Эседулла Абачев. Ряд сенаторов переподтвердили свои полномочия.", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Одобренный СФ закон направлен на минимизацию рисков причинения вреда жизни и здоровью при эксплуатации аттракционов", "st": "Одобренный СФ закон направлен на минимизацию рисков причинения вреда жизни и здоровью при эксплуатации аттракционов", "u": "http://council.gov.ru/events/news/177915/", "x": "Устанавливаются единые для всех регионов правовые и организационные основы деятельности в этой сфере.", "sut": "Сенаторы одобрили Федеральный закон «Об аттракционах». По этому вопросу выступил заместитель председателя Комитета СФ по экономической политике Арсен Каноков. Документ был разработан Законодательным Собранием Санкт-Петербурга. Он направлен на минимизацию рисков причинения вреда жизни и здоровью граждан.", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Уточнены наименования платежей за пользование недрами", "st": "Уточнены наименования платежей за пользование недрами", "u": "http://council.gov.ru/events/news/177914/", "x": "Закон был внесён Брянской областной думой.", "sut": "Совет Федерации одобрил изменения в статьи 51 и 57 Бюджетного кодекса РФ, уточняющие наименования отдельных платежей за пользование недрами.", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Финансовые организации смогут передавать обработку данных на аутсорсинг аккредитованным IT-компаниям", "st": "Финансовые организации смогут передавать обработку данных на аутсорсинг аккредитованным IT-компаниям", "u": "http://council.gov.ru/events/news/177913/", "x": "Закон представил один из его соавторов – М. Ульбашев.", "sut": "Совет Федерации одобрил закон о внесении изменений в отдельные законодательные акты РФ в части совершенствования правовых основ для аутсорсинга информационных технологий и использования облачных услуг финансовыми организациями. Закон устанавливает комплексное регулирование отношений, возникающих при привлечении участниками финансового рынка организаций для сбора, обработки и хранения информации ограниченного доступа, в том числе содержащей персональные данные и банковскую тайну.", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Выступление", "t": "Перед сенаторами выступила генеральный директор Государственного центрального музея современной истории России И. Великанова", "st": "Перед сенаторами выступила генеральный директор Государственного центрального музея современной истории России И. Великанова", "u": "http://council.gov.ru/events/news/177912/", "sut": "Она представила просветительский продукт музея — интерактивную карту «Россия — Родина моя».", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Правительственный час", "t": "Д. Мантуров рассказал сенаторам об основных направлениях развития промышленности", "st": "Д. Мантуров рассказал сенаторам об основных направлениях развития промышленности", "u": "http://council.gov.ru/events/news/177911/", "x": "В ходе «правительственного часа» парламентарии обсудили с первым вице-премьером ход реализации национальных проектов и обеспечение технологического лидерства.", "sut": "В рамках «правительственного часа» в Совете Федерации с докладом о развитии промышленности выступил первый заместитель Председателя Правительства РФ Денис Мантуров. По словам Дениса Мантурова, по направлениям, зависящим от инвестиционного спроса, результаты пока ниже, однако появляются признаки восстановления объемов производств, ориентированных на потребительскую активность, в частности в автомобильной промышленности, мебельной отрасли и отдельных сегментах бытовой электроники.", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Выступления сенаторов", "t": "На «парламентской разминке» затронуты темы поддержки образования, здравоохранения, социально-экономического развития субъектов РФ", "st": "На «парламентской разминке» затронуты темы поддержки образования, здравоохранения, социально-экономического развития субъектов РФ", "u": "http://council.gov.ru/events/news/177910/", "x": "Сенаторы выступили по актуальным социально-экономическим, политическим и иным вопросам.", "sut": "Председатель Комитета СФ по науке, образованию и культуре Лилия Гумерова рассказала о прошедшем в Туле 15 октября заседании Экспертного совета при Совете при Президенте РФ по реализации государственной демографической и семейной политики. Сенатор также проинформировала о проводимой профильным Комитетом системной работе по мониторингу процесса закупки в регионах учебников для образовательных организаций. При этом особое внимание уделяется вопросам ценообразования на учебные пособия, снижения их стоимости.", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Внесены изменения в Земельный кодекс РФ в целях совершенствования отдельных законодательных норм", "st": "Внесены изменения в Земельный кодекс РФ в целях совершенствования отдельных законодательных норм", "u": "http://council.gov.ru/events/news/177909/", "x": "Документ представил член Комитета СФ по аграрно-продовольственной политике и природопользованию Г. Ягубов.", "sut": "На 621-м заседании Совет Федерации одобрил внесение изменений в Земельный кодекс РФ. Закон был разработан в целях совершенствования отдельных законодательных норм о земельных участках, ограниченных в обороте и изъятых из оборота.", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Ратифицировано", "t": "Россия и Китай совместно построят второй главный путь на трансграничном участке железной дороги Забайкальск – Маньчжурия", "st": "Россия и Китай совместно построят второй главный путь на трансграничном участке железной дороги Забайкальск – Маньчжурия", "u": "http://council.gov.ru/events/news/177908/", "x": "Сенаторы ратифицировали соответствующее межправительственное соглашение.", "sut": "В ходе 621-го заседания Совета Федерации сенаторы ратифицировали соглашение между Правительством Российской Федерации и Правительством Китайской Народной Республики о совместном строительстве второго главного пути колеи 1435 мм на трансграничном участке железной дороги Забайкальск – Маньчжурия. «Документ создаёт правовую основу для строительства объекта трансграничной железнодорожной инфраструктуры и необходимые условия для увеличения объемов передачи грузов между пограничными станциями».", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Повышается эффективность механизмов правовой помощи между компетентными ведомствами на пространстве СНГ", "st": "Повышается эффективность механизмов правовой помощи между компетентными ведомствами на пространстве СНГ", "u": "http://council.gov.ru/events/news/177907/", "x": "Ратифицировано соглашение о сотрудничестве по обмену информацией при осуществлении принудительного исполнения судебных актов.", "sut": "Документ позволит обеспечить исполнение судебных актов и актов иных уполномоченных органов, а также повысит эффективность механизмов правовой помощи. Соглашение устанавливает основные форматы обмена информацией между компетентными ведомствами сторон при проведении процедур принудительного исполнения. Таким образом, у должников станет меньше возможностей скрыть свои активы, если они уедут в одну из стран СНГ, подписавших соглашение. Взыскание долгов перестанет зависеть от того, где физически находится должник и его активы.", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Сенаторы ратифицировали соглашение об основах отношений между Российской Федерацией и Буркина-Фасо", "st": "Сенаторы ратифицировали соглашение об основах отношений между Российской Федерацией и Буркина-Фасо", "u": "http://council.gov.ru/events/news/177906/", "x": "Страны развивают отношения на основе уважения и защиты их национальных интересов, а также общепризнанных принципов и норм международного права.", "sut": "В ходе 621-го заседания Совета Федерации сенаторы одобрили Федеральный закон «О ратификации Соглашения об основах отношений между Российской Федерацией и Буркина-Фасо». Сенатор напомнил, что соглашение было подписано в феврале 2026 года в Москве. Документ направлен на установление правовой основы межгосударственных отношений между двумя странами.", "sfi": 1}, {"o": "sf", "d": "28.10.2026", "ty": "заседание", "k": "", "stt": "Одобрено", "t": "Ратифицирован Протокол о развитии ВТС с Киргизией", "st": "Ратифицирован Протокол о развитии ВТС с Киргизией", "u": "http://council.gov.ru/events/news/177905/", "x": "Уточнены уполномоченные органы и организации, осуществляющие непосредственное взаимодействие по вопросам исполнения договора о военно-техническом сотрудничестве.", "sut": "В ходе 621-го заседания Совета Федерации сенаторы одобрили Федеральный закон «О ратификации Протокола о внесении изменений в Договор между Российской Федерацией и Киргизской Республикой о развитии военно-технического сотрудничества от 20 июня 2017 года». По его словам, документ направлен на совершенствование и упрощение порядка осуществления военно-технического сотрудничества между Российской Федерацией и Киргизской Республикой.", "sfi": 1}];
